const payload = $json.body || {};
const appointment = payload.appointment || {};
const previous = appointment.previous_patient || {};
const replacement = appointment.replacement_patient || {};
const professional = appointment.professional || {};

if (payload.event !== 'appointment.replaced') throw new Error('Evento invalido: esperado appointment.replaced.');
if (!payload.event_id || !appointment.id || !appointment.google_event_id || !appointment.starts_at) throw new Error('Payload incompleto: event_id, appointment.id, google_event_id e starts_at sao obrigatorios.');
function whatsappNumber(value, label) {
  let digits = String(value || '').replace(/\D/g, '');
  if (digits.length === 10 || digits.length === 11) digits = `55${digits}`;
  if (digits.length < 12 || digits.length > 13) throw new Error(`Telefone ${label} ausente ou invalido.`);
  return `${digits}@s.whatsapp.net`;
}
if (!previous.name || !replacement.name || !professional.name) throw new Error('Nomes dos pacientes e do profissional sao obrigatorios.');
const professionalEmail = String(professional.email || '').trim().toLowerCase();
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(professionalEmail)) throw new Error('E-mail do profissional ausente ou invalido.');
const startsAt = new Date(appointment.starts_at);
if (Number.isNaN(startsAt.getTime())) throw new Error('Data do agendamento invalida.');
const date = new Intl.DateTimeFormat('pt-BR', { timeZone: 'America/Sao_Paulo', day: '2-digit', month: '2-digit', year: 'numeric' }).format(startsAt);
const time = new Intl.DateTimeFormat('pt-BR', { timeZone: 'America/Sao_Paulo', hour: '2-digit', minute: '2-digit', hour12: false }).format(startsAt);
const specialty = professional.specialty || '';
const description = [`Motivo da consulta: ${replacement.reason || ''}`, `Especialidade: ${specialty}`, `Profissional: ${professional.name}`, `E-mail do cliente: ${replacement.email || ''}`, `Telefone: ${replacement.phone || ''}`].join('\n');
return [{ json: {
  eventId: payload.event_id, appointmentId: appointment.id, googleEventId: appointment.google_event_id, professionalEmail,
  summary: `Agendamento: ${replacement.name}`, description,
  previousPatientNumber: whatsappNumber(previous.phone, 'do paciente anterior'),
  replacementPatientNumber: whatsappNumber(replacement.phone, 'do novo paciente'),
  professionalNumber: whatsappNumber(professional.phone, 'do profissional'),
  previousPatientMessage: `Ola, ${previous.name}. Sua desistencia do agendamento de ${date}, as ${time}, foi registrada.\n\nClinica Maieutica`,
  replacementPatientMessage: `Ola, ${replacement.name}! Seu encaixe com ${professional.name}${specialty ? ` (${specialty})` : ''} foi confirmado para ${date}, as ${time}.\n\nClinica Maieutica`,
  professionalMessage: `Ola, ${professional.name}. Houve uma substituicao no atendimento de ${date}, as ${time}.\n\nNovo paciente: ${replacement.name}\nContato: ${replacement.phone}\n\nClinica Maieutica`
} }];
